import{_ as i,l as n,o as e,c as s,v as r,p as l,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"模式演化与迁移","description":"","frontmatter":{"title":"模式演化与迁移","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/schema-migration.md","filePath":"cs/schema-migration.md","lastUpdated":1789023840000}'),h={name:"cs/schema-migration.md"};function E(m,a,A,_,u,D){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="模式演化与迁移" tabindex="-1">模式演化与迁移 <a class="header-anchor" href="#模式演化与迁移" aria-label="Permalink to &quot;模式演化与迁移&quot;">​</a></h1><div class="epigraph"><p>模式会变：加列、改约束、拆表。迁移是把旧实例变成新实例的事务脚本，失败必须停在可恢复的状态。</p><footer>—— 据 Sjøberg 对模式演化；Ramakrishnan and Gehrke；Curino et al. 对数据库演化工具的整理</footer></div><p><a href="/cs/savepoints">上一课</a>给出事务内部分撤销。本课不重定义 UNDO。缺口是<strong>模式本身是版本化对象</strong>：应用要发新版本，表结构、约束、视图定义一起变。主干关系模型假设模式给定；进阶必须处理「给定」会过期。迁移（migration）是有序 DDL + 数据回填，通常包在事务或可重入步骤里。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加可空列往往便宜；加 <code>NOT NULL</code> 无默认值则要先回填。改列类型可能重写整表。拆表是 <a href="/cs/normal-forms">范式</a> 在时间轴上的再执行：先建新表、拷数据、改写应用、再删旧列。缺口不是某家 <code>ALTER</code> 语法，而是合同：每一步之后约束仍成立，失败可重跑或回滚，读写应用有窗口看到哪一版模式。</p><p>在线变更：大表加索引会锁写。有的引擎用拷贝表、触发器双写、切名的方式缩短锁窗。本课点名策略，不把每家 Online DDL 当标准代数。</p><p><span class="marginnote">扩缩容分片是后课分布式问题。本课单库逻辑模式。版本号表（schema_migrations）记录已应用脚本，是工程惯例，不是关系理论新原语。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>正向迁移：版本 \\(n\\) 到 \\(n{+}1\\) 的脚本，幂等更好。回滚脚本：不是总能自动生成（删列可逆，丢数据的合并不可逆）。扩展–迁移–收缩：先加新结构（扩展），应用双写或读新，再回填（迁移），最后删旧结构（收缩），避免「改完立刻不兼容」。</p><p>视图与存储过程依赖列名：改名要先改定义。约束与触发器课已说明不变式；迁移中途可能短暂放松约束，必须在脚本末恢复，并处理违反行。</p>',10)),(e(),l(p,null,{default:t(()=>[c(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20V0%5B%22%E6%A8%A1%E5%BC%8F%20n%22%5D%20--%3E%20EXP%5B%22%E6%89%A9%E5%B1%95%3A%20%E5%8A%A0%E5%88%97%20%2F%20%E6%96%B0%E8%A1%A8%22%5D%0A%20%20EXP%20--%3E%20FILL%5B%22%E5%9B%9E%E5%A1%AB%E4%B8%8E%E5%8F%8C%E5%86%99%22%5D%0A%20%20FILL%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%E5%88%87%E8%AF%BB%22%5D%0A%20%20APP%20--%3E%20SHR%5B%22%E6%94%B6%E7%BC%A9%3A%20%E5%88%A0%E6%97%A7%22%5D%0A%20%20SHR%20--%3E%20V1%5B%22%E6%A8%A1%E5%BC%8F%20n%2B1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DDL 的事务性因引擎而异：有的 <code>ALTER</code> 可与 DML 同事务并回滚，有的隐式提交。保存点帮不上隐式提交。锁：改表可能拿 ACCESS EXCLUSIVE，与长查询冲突——这是运维窗口问题，不是代数。</p><p>兼容性：旧应用读新模式应仍能跑（只加列、不加强制约束）直到应用升级。这是数据独立性在时间上的版本：外模式尽量稳，内模式可以先变。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 ORM 迁移工具的文件格式——下一课阻抗失配会碰到它们生成的 SQL。也不把蓝绿数据库集群当本课必做。复制环境里 DDL 如何跟逻辑日志走，后课 CDC 再接。</p><p>后课默认：模式变更是带版本的脚本，不是生产上手改列。下一课 ORM：对象图与关系之间的缝，迁移工具常从这边生成。</p><p>不可逆迁移要当数据丢失预算显式签字，不能靠「事务回滚」幻想。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>迁移把实例从模式 \\(n\\) 送到 \\(n{+}1\\)，约束在步骤边界成立。</li><li>扩展–迁移–收缩缩短不兼容窗口；DDL 事务性因引擎而异。</li><li>ORM 阻抗下一课：对象与表的翻译如何把迁移变复杂。</li><li>出处：Sjøberg；Ramakrishnan and Gehrke；Curino 等演化工作。</li></ul>',9))])}const P=i(h,[["render",E]]);export{B as __pageData,P as default};
